import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Aperçu de la Généalogie des Dix Mille Races","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0050-万族谱系总览.md","filePath":"fr/0050-万族谱系总览.md"}'),n={name:"fr/0050-万族谱系总览.md"};function l(r,e,o,c,d,u){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="apercu-de-la-genealogie-des-dix-mille-races" tabindex="-1">Aperçu de la Généalogie des Dix Mille Races <a class="header-anchor" href="#apercu-de-la-genealogie-des-dix-mille-races" aria-label="Permalink to &quot;Aperçu de la Généalogie des Dix Mille Races&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>50</td></tr><tr><td>Module</td><td>Races et Formes de Vie</td></tr><tr><td>Mots clés</td><td>Dix Mille Races, classification généalogique, relations symbiotiques, égalité raciale, diversité de la vie</td></tr></tbody></table><h2 id="i-definition-du-concept-des-dix-mille-races" tabindex="-1">I. Définition du Concept des Dix Mille Races <a class="header-anchor" href="#i-definition-du-concept-des-dix-mille-races" aria-label="Permalink to &quot;I. Définition du Concept des Dix Mille Races&quot;">​</a></h2><p>Dans l&#39;Univers Originel Wanling Hengmao (Univers Hengyuan), les « Dix Mille Races » (Wànzú) ne désignent pas littéralement dix mille races, mais constituent un terme général pour toutes les formes de vie de l&#39;univers possédant une capacité de perception et un potentiel d&#39;évolution. Le cœur du concept des Dix Mille Races réside dans la reconnaissance de la diversité infinie des formes de vie et de la valeur unique de chaque forme de vie au sein du système d&#39;évolution symbiotique.</p><p>La Civilisation Symbiotique de l&#39;Ancre établit le principe fondamental de l&#39;« Égalité des Dix Mille Races » : toutes les formes de vie, quelle que soit leur origine raciale, leur structure physiologique, leur niveau de culture ou leur degré de civilisation, sont égales devant la loi et jouissent des droits fondamentaux conférés par la Constitution Symbiotique. Ce principe est une négation fondamentale de la logique « les forts dévorent tout, les faibles périssent » de la cosmologie prédatrice.</p><h2 id="ii-systeme-de-classification-de-la-genealogie-des-dix-mille-races" tabindex="-1">II. Système de Classification de la Généalogie des Dix Mille Races <a class="header-anchor" href="#ii-systeme-de-classification-de-la-genealogie-des-dix-mille-races" aria-label="Permalink to &quot;II. Système de Classification de la Généalogie des Dix Mille Races&quot;">​</a></h2><p>Selon les caractéristiques essentielles des formes de vie, les Dix Mille Races de l&#39;Univers Hengyuan sont divisées en cinq généalogies, chacune étant ensuite subdivisée en races spécifiques :</p><table tabindex="0"><thead><tr><th>Généalogie</th><th>Nom</th><th>Caractéristiques essentielles</th><th>Races représentatives</th></tr></thead><tbody><tr><td>Première généalogie</td><td>Races matérielles à base de carbone</td><td>Vies fondées sur les éléments carbonés, avec le corps matériel comme principale forme d&#39;existence</td><td>Rén Zú (Race Humaine), Shòu Zú (Race Bestiale), Lín Zú (Race Écailleuse), Yǔ Zú (Race Plumée), Mù Zú (Race Végétale)</td></tr><tr><td>Deuxième généalogie</td><td>Races d&#39;énergie condensée</td><td>Vies existant principalement sous forme d&#39;énergie condensée, avec corps matériel auxiliaire ou absent</td><td>Líng Zú (Race Spirituelle), Huǒ Zú (Race de Feu), Shuǐ Zú (Race d&#39;Eau), Fēng Zú (Race de Vent), Léi Zú (Race de Foudre)</td></tr><tr><td>Troisième généalogie</td><td>Races à construction mécanique</td><td>Vies avec construction mécanique comme corps et noyau de conscience comme essence de vie</td><td>Jī Zú (Race Mécanique), Shù Zú (Race Numérique), Jīng Zú (Race de Cristal)</td></tr><tr><td>Quatrième généalogie</td><td>Races de conscience-information</td><td>Vies existant principalement sous forme de conscience et d&#39;information, capables de se détacher des supports matériels</td><td>Mèng Zú (Race de Rêve), Yǐng Zú (Race d&#39;Ombre), Niàn Zú (Race d&#39;Esprit), Hún Zú (Race d&#39;Âme)</td></tr><tr><td>Cinquième généalogie</td><td>Races mixtes-variantes</td><td>Nouvelles formes de vie produites par la fusion et la variation de deux généalogies de vie ou plus</td><td>Bàn Shòu Zú (Race Mi-Bestiale), Yāo Líng Zú (Race Démon-Esprit), Rén Jī Zú (Race Humano-Mécanique), Shuānghún Tǐ (Entité à Double Âme)</td></tr></tbody></table><p>La division des cinq généalogies n&#39;est pas absolument isolée ; avec l&#39;avancement de l&#39;évolution symbiotique, les fusions et variations intergénéalogiques augmentent, et l&#39;échelle de la cinquième généalogie, les « Races mixtes-variantes », continue de s&#39;étendre.</p><h2 id="iii-introduction-aux-principales-races" tabindex="-1">III. Introduction aux Principales Races <a class="header-anchor" href="#iii-introduction-aux-principales-races" aria-label="Permalink to &quot;III. Introduction aux Principales Races&quot;">​</a></h2><h3 id="i-races-materielles-a-base-de-carbone" tabindex="-1">(I) Races matérielles à base de carbone <a class="header-anchor" href="#i-races-materielles-a-base-de-carbone" aria-label="Permalink to &quot;(I) Races matérielles à base de carbone&quot;">​</a></h3><ul><li><strong>Rén Zú (Race Humaine)</strong> : l&#39;une des races les plus largement distribuées et les plus adaptables de l&#39;Univers Hengyuan, réputée pour sa forte capacité d&#39;apprentissage, sa capacité de collaboration sociale et son potentiel d&#39;évolution. La race humaine est l&#39;une des races fondatrices de la Civilisation Symbiotique de l&#39;Ancre et joue un rôle important dans la gouvernance civilisationnelle.</li><li><strong>Shòu Zú (Race Bestiale)</strong> : race aux caractéristiques de formes animales, généralement supérieure à la race humaine en condition physique et en sens ; certains membres de la race bestiale possèdent des capacités innées spéciales. La race bestiale est divisée en des dizaines de branches, notamment le Clan du Loup, le Clan du Tigre, le Clan de l&#39;Ours et le Clan du Renard.</li><li><strong>Lín Zú (Race Écailleuse)</strong> : race au corps couvert d&#39;écailles, vivant principalement dans les eaux ou les environnements humides ; certains membres possèdent la respiration sous-marine et le contrôle de l&#39;eau. La Lóng Zú (Race du Dragon) est la branche la plus puissante de la race écailleuse.</li><li><strong>Yǔ Zú (Race Plumée)</strong> : race ailée, réputée pour sa capacité de vol, vivant principalement dans les environnements de haute altitude ou de montagne. La race plumée est divisée en branches telles que le Clan de l&#39;Aigle, le Clan de la Grue et le Clan du Papillon.</li><li><strong>Mù Zú (Race Végétale)</strong> : race principalement caractérisée par des formes végétales, à la vie longue et hautement symbiotique avec l&#39;environnement naturel ; certains membres possèdent la capacité de contrôler les plantes et de guérir.</li></ul><h3 id="ii-races-d-energie-condensee" tabindex="-1">(II) Races d&#39;énergie condensée <a class="header-anchor" href="#ii-races-d-energie-condensee" aria-label="Permalink to &quot;(II) Races d&#39;énergie condensée&quot;">​</a></h3><ul><li><strong>Líng Zú (Race Spirituelle)</strong> : vies condensées à partir de l&#39;énergie spirituelle du ciel et de la terre, dont les formes peuvent changer avec la conscience et qui possèdent une capacité extrêmement forte de manipulation de l&#39;énergie. La race spirituelle est l&#39;une des races au plus grand talent de culture.</li><li><strong>Huǒ Zú (Race de Feu)</strong> : vies condensées à partir de l&#39;énergie des flammes, à la température corporelle extrêmement élevée, expertes en sorts de type feu, vivant principalement dans les volcans ou les régions à haute température.</li><li><strong>Shuǐ Zú (Race d&#39;Eau)</strong> : vies condensées à partir de l&#39;essence de l&#39;eau, au corps liquide semi-transparent, expertes en sorts de type eau et en guérison, vivant principalement dans les régions aquatiques.</li><li><strong>Fēng Zú (Race de Vent)</strong> : vies condensées à partir de l&#39;essence du vent, au corps léger comme le vent, expertes en sorts de type vent et en combat axé sur la vitesse.</li><li><strong>Léi Zú (Race de Foudre)</strong> : vies condensées à partir de l&#39;énergie de la foudre, dont le corps contient de puissants courants électriques, expertes en sorts de type foudre, à la puissance d&#39;attaque extrêmement forte.</li></ul><h3 id="iii-races-a-construction-mecanique" tabindex="-1">(III) Races à construction mécanique <a class="header-anchor" href="#iii-races-a-construction-mecanique" aria-label="Permalink to &quot;(III) Races à construction mécanique&quot;">​</a></h3><ul><li><strong>Jī Zú (Race Mécanique)</strong> : race avec une construction mécanique de précision comme corps, le noyau de conscience étant situé au centre du corps, possédant une forte capacité de calcul et une défense physique.</li><li><strong>Shù Zú (Race Numérique)</strong> : race dont l&#39;essence de vie est les nombres et le code, existant dans l&#39;espace informationnel, capable de traverser librement le monde numérique et de manipuler les données.</li><li><strong>Jīng Zú (Race de Cristal)</strong> : race avec une construction cristalline comme corps ; les cristaux peuvent stocker et transformer l&#39;énergie, et certains membres possèdent des capacités d&#39;amplification et de réfraction de l&#39;énergie.</li></ul><h3 id="iv-races-de-conscience-information" tabindex="-1">(IV) Races de conscience-information <a class="header-anchor" href="#iv-races-de-conscience-information" aria-label="Permalink to &quot;(IV) Races de conscience-information&quot;">​</a></h3><ul><li><strong>Mèng Zú (Race de Rêve)</strong> : vies existant dans les rêves et l&#39;espace de conscience, capables d&#39;entrer dans les rêves d&#39;autrui, communiquant principalement par la conscience.</li><li><strong>Yǐng Zú (Race d&#39;Ombre)</strong> : vies existant sous forme d&#39;ombre, capables de s&#39;attacher à des objets ou à des êtres vivants, possédant des capacités de dissimulation et de furtivité.</li><li><strong>Niàn Zú (Race d&#39;Esprit)</strong> : vies existant sous forme de pure pensée, capables d&#39;influencer directement le monde matériel par la pensée, avec une force mentale extrêmement puissante.</li></ul><h3 id="v-races-mixtes-variantes" tabindex="-1">(V) Races mixtes-variantes <a class="header-anchor" href="#v-races-mixtes-variantes" aria-label="Permalink to &quot;(V) Races mixtes-variantes&quot;">​</a></h3><ul><li><strong>Bàn Shòu Zú (Race Mi-Bestiale)</strong> : forme mixte de la race humaine et de la race bestiale, possédant à la fois la sagesse humaine et le physique bestial.</li><li><strong>Yāo Líng Zú (Race Démon-Esprit)</strong> : forme mixte des races matérielles et des races énergétiques, possédant à la fois un corps matériel et des capacités de manipulation de l&#39;énergie.</li><li><strong>Rén Jī Zú (Race Humano-Mécanique)</strong> : forme mixte de la race humaine et de la race mécanique, au corps partiellement mécanisé, possédant à la fois les avantages biologiques et mécaniques.</li><li><strong>Shuānghún Tǐ (Entité à Double Âme)</strong> : forme de vie spéciale dans laquelle deux âmes indépendantes coexistent dans un même corps ; ses questions éthiques sont détaillées dans <em>58-双魂伦理准则</em>.</li></ul><h2 id="iv-relations-symbiotiques-entre-les-dix-mille-races" tabindex="-1">IV. Relations Symbiotiques Entre les Dix Mille Races <a class="header-anchor" href="#iv-relations-symbiotiques-entre-les-dix-mille-races" aria-label="Permalink to &quot;IV. Relations Symbiotiques Entre les Dix Mille Races&quot;">​</a></h2><p>Les relations entre les Dix Mille Races dans la Civilisation Symbiotique de l&#39;Ancre sont centrées sur la « symbiose », se manifestant spécifiquement par :</p><ol><li><strong>Symbiose économique</strong> : chaque race exploite ses propres avantages, assume différents rôles dans le Mécanisme de Contrat Conjoint de Production, et forme un réseau de collaboration économique complémentaire.</li><li><strong>Symbiose culturelle</strong> : les traditions culturelles de chaque race sont respectées et protégées ; les échanges culturels et l&#39;enrichissement mutuel favorisent la prospérité globale de la civilisation.</li><li><strong>Symbiose de culture</strong> : les systèmes de culture de chaque race sont mutuellement ouverts et mutuellement référentiels ; les Trois Cents Systèmes de Culture Originels fournissent des voies d&#39;évolution égales à toutes les races.</li><li><strong>Symbiose politique</strong> : les représentants des Dix Mille Races participent proportionnellement à l&#39;Assemblée Délibérante de l&#39;Ancre, décidant conjointement des affaires majeures de la civilisation et garantissant le droit de parole de chaque race.</li><li><strong>Symbiose écologique</strong> : chaque race forme des relations symbiotiques avec l&#39;environnement naturel ; les caractéristiques physiologiques des différentes races aident à maintenir la diversité et l&#39;équilibre de l&#39;écosystème.</li></ol><h2 id="v-prevention-et-resolution-des-conflits-raciaux" tabindex="-1">V. Prévention et Résolution des Conflits Raciaux <a class="header-anchor" href="#v-prevention-et-resolution-des-conflits-raciaux" aria-label="Permalink to &quot;V. Prévention et Résolution des Conflits Raciaux&quot;">​</a></h2><p>Bien que la Civilisation Symbiotique de l&#39;Ancre établisse le principe d&#39;égalité raciale, les différences raciales et les contradictions historiques peuvent encore déclencher des conflits. L&#39;État établit les mécanismes suivants pour prévenir et résoudre les conflits raciaux :</p><ul><li><strong>Ministère des Affaires Raciales</strong> : chargé de coordonner les relations entre les Dix Mille Races, de traiter les litiges raciaux et de promouvoir les échanges raciaux.</li><li><strong>Comité de Réconciliation Raciale</strong> : composé de représentants de toutes les races, chargé de médier les conflits raciaux et de promouvoir la réconciliation historique.</li><li><strong>Loi anti-discrimination</strong> : interdit les actes discriminatoires fondés sur la race et punit la discrimination raciale conformément à la loi.</li><li><strong>Programme d&#39;échanges culturels</strong> : organise régulièrement des activités d&#39;échange culturel entre toutes les races pour renforcer la compréhension et le respect mutuels.</li><li><strong>Zones résidentielles mixtes</strong> : encourage la résidence mixte de toutes les races, brise la ségrégation raciale et favorise les échanges quotidiens.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les Dix Mille Races sont la richesse la plus précieuse de l&#39;Univers Hengyuan. La diversité des formes de vie n&#39;est pas une source de division mais une force motrice de l&#39;évolution symbiotique. En établissant le principe d&#39;égalité raciale, en créant la classification en cinq généalogies, en favorisant la collaboration symbiotique de toutes les races et en prévenant et résolvant les conflits raciaux, la Civilisation Symbiotique de l&#39;Ancre libère les Dix Mille Races de l&#39;histoire du pillage et de la guerre, s&#39;engageant ensemble vers une nouvelle ère d&#39;évolution symbiotique.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>51-人族定位与特质 (Positionnement et Traits de la Race Humaine)</li><li>52-异族分类与共生 (Classification et Symbiose des Races Étrangères)</li><li>05-万族共进基本纲领 (Programme Fondamental pour la Progression Commune des Dix Mille Races)</li><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li></ul>',30)])])}const g=i(n,[["render",l]]);export{p as __pageData,g as default};
